// The shape of a country's map for the Road Agency Directory's map view.
// One file per country (us.ts), generated by scripts/make-agency-maps.mjs.
// Coordinates are SVG user units inside `viewBox`.

export interface MapRegion {
  /** ISO 3166-2, matching an agency's `region`. */
  code: string
  /** Short label drawn on the map, e.g. "OR". */
  abbr: string
  /** SVG path data for the outline. */
  d: string
  /** Where the label is drawn: the shape's center, a callout box, or an inset's corner. */
  label: [number, number]
  /** A labeled box beside the map for a state too small to tap, joined by a leader line from `from`. */
  callout?: { x: number, y: number, w: number, h: number, from: [number, number] }
  /** A territory's own framed box. */
  inset?: { x: number, y: number, w: number, h: number }
}

export interface RegionMap {
  viewBox: [number, number, number, number]
  regions: MapRegion[]
}
